class Solution { vector<vector<int>> buildCosts(const string& s){int n=s.size(),INF=1000000;vector<vector<int>> mismatchPrefix(n,vector<int>(n+1));for(int gap=1;gap<n;++gap)for(int index=0;index+gap<n;++index)mismatchPrefix[gap][index+1]=mismatchPrefix[gap][index]+(s[index]!=s[index+gap]);vector<vector<int>> change(n,vector<int>(n,INF)),divisorCost(n,vector<int>(n));for(int divisor=1;2*divisor<=n;++divisor)for(int length=2*divisor;length<=n;length+=divisor){int gap=length-divisor;for(int left=0;left+length<=n;++left){int right=left+length-1;int cost=mismatchPrefix[gap][left+divisor]-mismatchPrefix[gap][left];if(length>=4*divisor)cost+=divisorCost[left+divisor][right-divisor];divisorCost[left][right]=cost;change[left][right]=min(change[left][right],cost);}}return change;}public:int minimumChanges(string s,int k){int n=s.size(),INF=1000000;vector<vector<int>> change=buildCosts(s);vector<int> previous(n+1,INF);previous[0]=0;for(int parts=1;parts<=k;++parts){vector<int> current(n+1,INF);int minimumEnd=2*parts,maximumEnd=n-2*(k-parts);for(int end=minimumEnd;end<=maximumEnd;++end)for(int start=2*(parts-1);start<=end-2;++start)if(previous[start]<INF)current[end]=min(current[end],previous[start]+change[start][end-1]);previous.swap(current);}return previous[n];} };
